const raw = $input.first().json || {};
const wf = raw.workflow || {};
const exec = raw.execution || {};
const err = raw.error || {};
const node = raw.node || {};

const wfName = String(wf.name || raw.workflowName || raw.workflow_id || 'unknown');
const wfId = String(wf.id || raw.workflowId || raw.workflow_id || '');
const execId = String(exec.id || raw.executionId || raw.execution_id || '');
const nodeName = String(node.name || raw.lastNode || raw.node_name || 'unknown');
const errMsg = String(err.message || raw.errorMessage || raw.message || 'No error message');
const errName = String(err.name || raw.errorName || 'Error');
const errStack = String(err.stack || '');

let project_id = 'shared';
if (/^p1|lead|qualification|crm.?handoff|follow.?up|pipeline/i.test(wfName)) project_id = 'P1';
else if (/^p2|inbox|triage|review|operations.?brief|retention/i.test(wfName)) project_id = 'P2';
else if (/^p3|hubspot|airtable|reconcil|backfill|dead.?letter|sync.?health/i.test(wfName)) project_id = 'P3';

const stage = nodeName;
const lc = (errMsg + ' ' + errName).toLowerCase();
let severity = 'medium';
let retryable = false;
let error_code = 'unknown';
if (/401|403|unauthor|forbidden|invalid.?grant/.test(lc)) { severity = 'critical'; error_code = 'auth_error'; retryable = false; }
else if (/429|rate.?limit|too.?many.?requests/.test(lc)) { severity = 'high'; error_code = 'rate_limited'; retryable = true; }
else if (/5[0-9][0-9]|server|timeout|econn|network|socket|dns|getaddr/.test(lc)) { severity = 'high'; error_code = 'transient'; retryable = true; }
else if (/schema|validation|invalid|malformed|400|bad.?request|enum/.test(lc)) { severity = 'high'; error_code = 'schema_error'; retryable = false; }
else { error_code = (errName.slice(0, 40) || 'error'); }

const secretPat = /(sk-[a-zA-Z0-9]{8,}|Bearer\s+[a-zA-Z0-9._-]+|password["\s:=]+[^\s,]+|api[_-]?key["\s:=]+[^\s,]+|token["\s:=]+[^\s,]+|pat[a-zA-Z0-9]{8,})/gi;
const redact = s => String(s == null ? '' : s).replace(secretPat, '[REDACTED]').slice(0, 2000);
const sanitized_error = redact(errMsg + (errStack ? '\n' + errStack : ''));

const hash = s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(16); };
const fingerprint = hash(project_id + '|' + wfName + '|' + stage + '|' + error_code);
const correlation_id = String(raw.correlation_id || execId || 'err-' + fingerprint);

const replayData = raw.data || raw.items || raw.input || exec.data || null;
const has_replay = !!replayData;
const sanitized_input = has_replay ? redact(JSON.stringify(replayData)) : '';

const now = new Date().toISOString();
const attempt = Number(raw.attempt || exec.retryAttempt || 0);

return [{ json: {
  project_id, workflow_id: wfId, workflow_name: wfName, execution_id: execId,
  stage, status: 'failed', attempt, severity, error_code, retryable,
  correlation_id, fingerprint, sanitized_error, sanitized_input,
  has_replay, started_at: String(raw.started_at || exec.startedAt || now),
  completed_at: now, external_ids: '',
  replay_of: String(raw.replay_of || exec.retryOf || ''),
  alert_group_key: project_id + ':' + fingerprint
}}];
